    'Check how the data you delete interacts with other sections.' => 'সিস্টেমের মধ্যে থাকা অন্যান্য বিভাগ বা মডিউলগুলির সাথে কীভাবে মুছে ফেলা ডেটা ইন্টারঅ্যাক্ট করে তা সনাক্ত করুন এবং বুঝতে পারবেন।',
