    'Check the delivery address and contact details before continuing.' => 'আপনি চালিয়ে যাওয়ার আগে অনুগ্রহ করে ডেলিভারি ঠিকানা প্রাপকের তথ্য যোগাযোগের বিবরণ এবং বিতরণ তথ্য যাচাই করুন',
    'Check the links are correct, or buttons will redirect wrongly.' => 'অনুগ্রহ করে নিশ্চিত করুন যে প্রদত্ত লিঙ্কগুলি সঠিক অন্যথায় বোতামগুলি ভুল দিকে পুনঃনির্দেশিত হয়',
