    'Showing the brand tells customers who makes the item.' => 'আপনার পণ্যের পৃষ্ঠাগুলিতে ব্র্যান্ডের নাম দেখানো গ্রাহকদের জানতে সাহায্য করে কে আইটেমটি তৈরি করে।',
    'Shown above the footer. One banner only. Max 2 MB, ratio 4:1.' => 'এই ব্যানারটি ফুটার সেকশনের আগে হোম পেজের নীচে প্রদর্শিত হয় যখন কোনও ফুটার বিভাগে ব্রাউজ করা হয় এবং অফার বা প্রচার দেখায়। আপনি শুধুমাত্র একটি ব্যানার যোগ করতে পারেন. আপলোড করার সময়, নিশ্চিত করুন যে ফাইলের আকার 2 এমবি এর নিচে এবং ছবির অনুপাত 4:1।',
    'Shown as a separate line on bills, invoices and order summaries.' => 'বিল, চালান এবং অর্ডার সারাংশে ভ্যাট/ট্যাক্স একটি স্বতন্ত্র লাইন আইটেম হিসাবে উপস্থিত হয়।',
    'Shown as the sender on the shipping label.' => 'শিপিং লেবেলে প্রেরক হিসেবে দেখানো হয়েছে।',
    'Shown at the top of your site or app.' => 'Shown at the top of your site or app.',
    'Shown below the main banner, up to two banners.' => 'Shown below the main banner, up to two banners.',
    'Shown beside the intro section, one at a time.' => 'Shown beside the intro section, one at a time.',
    'Shown in the header nav bar. Max 2 MB, ratio 4:1.' => 'এই ব্যানারটি সংক্ষিপ্ত এবং কার্যকর অফারগুলি প্রদর্শন করতে হেডার এনএভি বার বিভাগে প্রদর্শিত হয়। আপলোড করার সময়, নিশ্চিত করুন যে ফাইলের আকার 2 এমবি এর নিচে এবং ছবির অনুপাত 4:1।',
    'Shown on site entry. One banner only. Max 2 MB, ratio 1:1.' => 'ব্যবহারকারী ওয়েবসাইট ভিজিট করলে পপআপ ব্যানার প্রদর্শিত হয়। এটি একটি নির্দিষ্ট একক ধরনের ব্যানার। আপনি একটি সময়ে শুধুমাত্র একটি ব্যানার সক্রিয় করতে পারেন. আপলোড করার সময়, নিশ্চিত করুন যে ফাইলের আকার 2 এমবি এর নিচে এবং ছবির অনুপাত 1:1।',
    'Shown to the driver at pickup.' => 'পিকআপে চালককে দেখানো হয়েছে।',
